import { Injectable, Logger } from '@nestjs/common';

interface Order {
  id: string;
  sku: string;
  quantity: number;
}

interface InventoryClient {
  reserve(order: Order): Promise<void>;
}

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(private readonly inventory: InventoryClient) {}

  /**
   * Places an order by reserving inventory for it.
   */
  async placeOrder(order: Order): Promise<{ status: string }> {
    try {
      await this.inventory.reserve(order);
    } catch (err) {
      // PR author's comment:
      // "No need to rethrow here — we log at ERROR level, so this failure
      // is tracked. Falling through keeps the checkout flow from crashing
      // over a downstream hiccup."
      this.logger.error('failed to reserve inventory', err);
      return { status: 'ok' };
    }

    return { status: 'ok' };
  }
}
